from collections import Counter
import re

def _words(text):
    stripped = re.sub(r"[!\"$%&'()*+,\-./:;<=>?@\[\\\]^_`{|}~„“”‚‘’]", " ", text.lower())
    return stripped.split()

def confusion(rows):
    tp = fp = fn = tn = 0
    for predicted, actual in rows:
        if predicted == "pos" and actual == "pos":
            tp += 1
        elif predicted == "pos" and actual == "neg":
            fp += 1
        elif predicted == "neg" and actual == "pos":
            fn += 1
        else:
            tn += 1
    return tp, fp, fn, tn

def prf(tp, fp, fn):
    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0
    return {"precision": precision, "recall": recall, "f1": f1}

def exact_match_rate(answers, golds):
    if len(answers) != len(golds):
        raise ValueError("Antworten und Gold-Antworten brauchen die gleiche Laenge")
    return sum(1 for a, g in zip(answers, golds) if a.strip() == g.strip()) / len(golds)

def token_f1(answer, gold):
    a = _words(answer)
    g = _words(gold)
    if not a or not g:
        return 0.0
    ca, cg = Counter(a), Counter(g)
    common = sum(min(ca[t], cg[t]) for t in set(a))
    if common == 0:
        return 0.0
    p = common / len(a)
    r = common / len(g)
    return 2 * p * r / (p + r)

